// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint amount, uint unlockTime) public {
        vm.assume(user != address(0));
        // Ensure the balance after deposit won't overflow
        vm.assume(amount <= type(uint256).max - 1 ether);
        // Give user ether
        vm.deal(user, amount + 1 ether);
        // First deposit to set balance exactly to amount (we deposit amount-1 ether? No, we just set balance via deposit)
        // Better: deposit (amount + 1 ether) then withdraw 1 ether to set balance to amount? But that's complex.
        // Simpler: deposit amount, then try to withdraw amount.
        // But we need balance >= MinSum (1 ether). So ensure amount >= 1 ether.
        vm.assume(amount >= 1 ether);
        // Set unlock time in the past, so it's immediately unlockable
        vm.assume(unlockTime <= block.timestamp);
        // Deposit
        vm.prank(user);
        c.Put{value: amount}(unlockTime);
        // Now try to withdraw exactly the balance
        uint balanceBefore = c.Acc(user).balance;
        // Should be amount. Use try/catch to handle revert
        bool reverted;
        vm.prank(user);
        try c.Collect(balanceBefore) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The general rule: withdraw of exact balance must succeed
        assertTrue(!reverted, "Withdraw of exact balance must succeed");
        // And balance after should be 0
        uint balanceAfter = c.Acc(user).balance;
        assertTrue(balanceAfter == 0, "Balance should be zero after full withdrawal");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 deposit, uint256 withdraw) public {
        vm.assume(user != address(0));
        // Constrain inputs to realistic values
        deposit = bound(deposit, 0, 100 ether);
        withdraw = bound(withdraw, 0, 100 ether);
        // Set up: fund the user and add enough balance so that MinSum (1 eth) is met
        vm.deal(user, deposit + 1 ether);
        // Deposit some money to meet MinSum and add balance
        vm.prank(user);
        c.Put{value: deposit + 1 ether}(0);
        // Now try to collect
        uint256 balanceBefore = c.Acc(user).balance;
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdraw));
        uint256 balanceAfter = c.Acc(user).balance;
        // General rule: if Collect succeeded, balance decreases by exactly withdraw or more; otherwise unchanged
        if (success) {
            assertTrue(balanceAfter <= balanceBefore - withdraw);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 amount, uint256 unlockTime, uint256 balance) public {
        // bound fuzz parameters to reasonable ranges
        amount = bound(amount, 1 ether, 100 ether);
        balance = bound(balance, amount, amount); // intentionally set balance equal to amount
        unlockTime = bound(unlockTime, 0, block.timestamp); // ensure unlock time has passed

        // fund the contract with enough ether to cover the user's balance
        vm.deal(address(c), balance);

        // set up user's balance by calling Put
        vm.deal(user, balance);
        vm.prank(user);
        c.Put{value: balance}(unlockTime);

        // Now test Collect with amount equal to balance
        vm.prank(user);
        (bool success, ) = address(c).call{gas: gasleft()}(abi.encodeWithSignature("Collect(uint256)", amount));

        // The property: when balance == amount and all conditions are met, Collect must revert in the buggy version
        // but succeed in the correct version. Here we assert it must succeed.
        assertTrue(success, "Collect should succeed when balance equals withdrawal amount");

        // Additionally, the user's balance should be zero after successful withdrawal
        (, uint256 userBalance) = c.Acc(user);
        assertTrue(userBalance == 0, "Balance must be zero after withdrawing exactly the balance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 deposit, uint256 unlockTimeOffset, uint256 minSum) public {
        vm.assume(deposit >= 1 ether);
        vm.assume(minSum <= deposit);
        uint256 unlockTime = block.timestamp + unlockTimeOffset;
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(unlockTime);
        // Now the balance is deposit, we try to withdraw exactly deposit
        vm.warp(block.timestamp + unlockTimeOffset + 1);
        vm.prank(user);
        bool success = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", deposit));
        // After call, check balance
        (uint256 balance,) = c.Acc(user);
        assertTrue(success && balance == 0, "failed eq condition");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address user, uint256 deposit, uint256 unlockTimeOffset) public {
        vm.assume(user != address(0));
        vm.assume(deposit >= 1 ether && deposit <= type(uint96).max); // to avoid overflow
        vm.assume(unlockTimeOffset <= 365 days);

        uint256 unlockTime = block.timestamp + unlockTimeOffset;

        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(unlockTime);

        // Fast forward past unlockTime
        vm.warp(block.timestamp + unlockTimeOffset + 1);

        // Now try to withdraw exactly the balance
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", deposit));

        // The reference must succeed when withdrawing exactly the balance
        assertTrue(success, "Collect should succeed when withdrawing full balance");
    }
}
